 let landed=false;for(let i=0;i<w.pellets;i++){let a=p.a+(w.pellets>1?(i/(w.pellets-1)-.5)*2*w.spread:0),dx=Math.cos(a),dy=Math.sin(a),nearest=this.ray(p.x,p.y,dx,dy).d,chosen=null;for(let e of this.enemies){if(!e.alive)continue;let ex=e.x-p.x,ey=e.y-p.y,along=ex*dx+ey*dy,perp=Math.abs(ex*dy-ey*dx),radius=e.type==='boss'?.64:.35;if(along>0&&along<nearest&&perp<radius){nearest=along;chosen=e}}if(chosen){this.hit(chosen,w.damage);landed=true}else{this.particles.push({x:p.x+dx*(nearest-.03),y:p.y+dy*(nearest-.03),life:.2,type:'spark'})}}
